//! @fls: hax_refine_as
//! @title: A base value refined with RefineAs
//! @lean(tier): supported
//! @lean(reason): aeneas fails on the implementations that `#[refinement_type]` generates for the newtype (`Missing trait impl` and `Could not convert the name to a pattern` on `hax__autogenerated_refinement__`); the refinement section of the input-language reference.

// The hax-lib API under test exists only in hax mode.
#![cfg(hax)]

use hax_lib::{RefineAs, Refinement};

#[hax_lib::refinement_type(|x| x <= 100)]
pub struct Percent(u8);

pub fn complement(p: u8) -> u8 {
    let refined: Percent = p.into_checked();
    100 - refined.get()
}

#[hax_test::equiv]
pub fn refined_from_base() -> bool {
    complement(30) == 70
}
